package com.harvestflow.registration.service.impl;
import com.harvestflow.api.domain.entity.User; import com.harvestflow.api.domain.enums.UserRole; import com.harvestflow.api.repository.UserRepository; import com.harvestflow.registration.dto.request.*; import com.harvestflow.registration.dto.response.*; import com.harvestflow.registration.entity.*; import com.harvestflow.registration.exception.*; import com.harvestflow.registration.repository.*; import com.harvestflow.registration.service.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.time.Instant; import java.util.*;
@Service public class RegistrationServiceImpl implements RegistrationService {
 private final RegistrationSessionRepository sessions; private final RegistrationDocumentRepository docs; private final UserRepository users; private final PasswordEncoder encoder; private final OtpService otp; private final AadhaarVerificationService aadhaar; private final DocumentStorageService storage;
 public RegistrationServiceImpl(RegistrationSessionRepository s,RegistrationDocumentRepository d,UserRepository u,PasswordEncoder e,OtpService o,AadhaarVerificationService a,DocumentStorageService st){sessions=s;docs=d;users=u;encoder=e;otp=o;aadhaar=a;storage=st;}
 @Transactional public RegistrationSessionResponse startRegistration(BasicDetailsRequest r){if(users.existsByUsername(r.username())||sessions.existsByUsername(r.username()))throw new UsernameAlreadyExistsException("Username already taken");if(users.existsByEmail(r.email()))throw new RegistrationException("Email already registered");RegistrationSession s=new RegistrationSession();s.setRegistrationToken(UUID.randomUUID().toString());s.setUsername(r.username());s.setPasswordHash(encoder.encode(r.password()));s.setFullName(r.fullName());s.setEmail(r.email());s.setExpiresAt(Instant.now().plusSeconds(3600));sessions.save(s);return new RegistrationSessionResponse(s.getRegistrationToken(),s.getStatus().name());}
 private RegistrationSession get(String token){RegistrationSession s=sessions.findByRegistrationToken(token).orElseThrow(()->new RegistrationException("Invalid or expired registration session"));if(Instant.now().isAfter(s.getExpiresAt())&&s.getStatus()!=RegistrationStatus.COMPLETED){s.setStatus(RegistrationStatus.EXPIRED);sessions.save(s);throw new RegistrationException("Registration session expired, please start again");}return s;}
 public OtpSentResponse sendMobileOtp(SendMobileOtpRequest r){RegistrationSession s=get(r.registrationToken());if(users.existsByMobile(r.mobileNumber())||sessions.existsByMobileNumber(r.mobileNumber()))throw new MobileAlreadyRegisteredException("Mobile number already registered");s.setMobileNumber(r.mobileNumber());s.setMobileVerified(false);sessions.save(s);otp.sendOtp(s.getId(),OtpPurpose.MOBILE_VERIFICATION,r.mobileNumber());return new OtpSentResponse("OTP_SENT",300,30);}
 @Transactional public OtpVerifiedResponse verifyMobileOtp(VerifyMobileOtpRequest r){RegistrationSession s=get(r.registrationToken());otp.verifyOtp(s.getId(),OtpPurpose.MOBILE_VERIFICATION,r.otp());s.setMobileVerified(true);s.setStatus(RegistrationStatus.MOBILE_VERIFIED);sessions.save(s);return new OtpVerifiedResponse(true,s.getStatus().name());}
 @Transactional public OtpSentResponse sendAadhaarOtp(SendAadhaarOtpRequest r){RegistrationSession s=get(r.registrationToken());require(s,RegistrationStatus.MOBILE_VERIFIED);s.setAadhaarNumber(r.aadhaarNumber());s.setAadhaarLast4(r.aadhaarNumber().substring(8));s.setAadhaarVerified(false);sessions.save(s);aadhaar.sendAadhaarOtp(s.getId(),r.aadhaarNumber());return new OtpSentResponse("OTP_SENT",300,30);}
 @Transactional public OtpVerifiedResponse verifyAadhaarOtp(VerifyAadhaarOtpRequest r){RegistrationSession s=get(r.registrationToken());aadhaar.verifyAadhaarOtp(s.getId(),r.otp());s.setAadhaarVerified(true);s.setStatus(RegistrationStatus.AADHAAR_VERIFIED);sessions.save(s);return new OtpVerifiedResponse(true,s.getStatus().name());}
 @Transactional public RegistrationSessionResponse selectRole(RoleSelectionRequest r){RegistrationSession s=get(r.registrationToken());require(s,RegistrationStatus.AADHAAR_VERIFIED);SelfRegisterableRole role;try{role=SelfRegisterableRole.valueOf(r.role().toUpperCase(Locale.ROOT));}catch(Exception e){throw new InvalidOrInternalRoleException("Role not allowed for self-registration");}s.setSelectedRole(role);s.setStatus(RegistrationStatus.ROLE_SELECTED);sessions.save(s);return new RegistrationSessionResponse(s.getRegistrationToken(),s.getStatus().name());}
 @Transactional public RegistrationSessionResponse submitAddress(AddressRequest r){RegistrationSession s=get(r.registrationToken());require(s,RegistrationStatus.ROLE_SELECTED);RegistrationAddress a=new RegistrationAddress();a.setAddressLine(r.addressLine());a.setVillageOrCity(r.villageOrCity());a.setDistrict(r.district());a.setState(r.state());a.setPincode(r.pincode());s.setAddress(a);s.setStatus(RegistrationStatus.ADDRESS_COMPLETED);sessions.save(s);return new RegistrationSessionResponse(s.getRegistrationToken(),s.getStatus().name());}
 public DocumentUploadResponse uploadKhetReceipt(String t,MultipartFile f){return upload(t,DocumentType.KHET_LAND_RECEIPT,f);} public DocumentUploadResponse uploadSignature(String t,MultipartFile f){return upload(t,DocumentType.SIGNATURE,f);} public DocumentUploadResponse uploadPhoto(String t,MultipartFile f){return upload(t,DocumentType.PHOTO,f);}
 @Transactional public DocumentUploadResponse upload(String t,DocumentType type,MultipartFile f){RegistrationSession s=get(t);require(s,RegistrationStatus.ADDRESS_COMPLETED);String path=storage.storeDocument(s.getId(),type,f);RegistrationDocument d=new RegistrationDocument();d.setRegistrationSessionId(s.getId());d.setDocumentType(type);d.setStoragePath(path);d.setOriginalFilename(Optional.ofNullable(f.getOriginalFilename()).orElse("document"));d.setContentType(f.getContentType());d.setFileSizeBytes(f.getSize());docs.deleteByRegistrationSessionIdAndDocumentType(s.getId(), type);docs.save(d);if(allDocs(s.getId())){s.setStatus(RegistrationStatus.DOCUMENTS_COMPLETED);sessions.save(s);}return new DocumentUploadResponse(type.name(),d.getOriginalFilename(),"UPLOADED");}
 private boolean allDocs(UUID id){Set<DocumentType> x=docs.findDocumentTypesBySessionId(id);return x.containsAll(EnumSet.of(DocumentType.KHET_LAND_RECEIPT,DocumentType.SIGNATURE,DocumentType.PHOTO));}
 @Transactional public RegistrationCompleteResponse submit(SubmitRegistrationRequest r){RegistrationSession s=get(r.registrationToken());if(!s.isMobileVerified())throw new RegistrationIncompleteException("Mobile number not verified");if(!s.isAadhaarVerified())throw new RegistrationIncompleteException("Aadhaar not verified");if(s.getSelectedRole()==null)throw new InvalidOrInternalRoleException("Role not selected");if(s.getAddress()==null)throw new RegistrationIncompleteException("Address incomplete");if(!allDocs(s.getId()))throw new DocumentValidationException("All required documents are missing or incomplete");if(users.existsByUsername(s.getUsername())||users.existsByEmail(s.getEmail())||users.existsByMobile(s.getMobileNumber()))throw new RegistrationException("Account details are already registered");User u=new User();u.setName(s.getFullName());u.setEmail(s.getEmail());u.setUsername(s.getUsername());u.setPasswordHash(s.getPasswordHash());u.setMobile(s.getMobileNumber());u.setLocation(String.join(", ",s.getAddress().getAddressLine(),s.getAddress().getVillageOrCity(),s.getAddress().getDistrict(),s.getAddress().getState(),s.getAddress().getPincode()));u.setRole(UserRole.valueOf(s.getSelectedRole().name()));u.setMustChangePassword(false);u.setActive(true);users.save(u);s.setStatus(RegistrationStatus.COMPLETED);s.setCompletedAt(Instant.now());sessions.save(s);return new RegistrationCompleteResponse(s.getUsername(),maskMobile(s.getMobileNumber()),"XXXX-XXXX-"+s.getAadhaarLast4(),s.getSelectedRole().name(),"COMPLETED");}
 private void require(RegistrationSession s,RegistrationStatus min){if(s.getStatus().ordinal()<min.ordinal())throw new RegistrationIncompleteException("Complete the previous registration step first");}
 private String maskMobile(String x){return "XXXXXX"+x.substring(x.length()-4);}
}
